    const dests = [['', 'Pack']].concat(bagTree().map(([b, d]) => [b.id, (d ? '\u2003'.repeat(d) + '↳ ' : '') + (b.name || 'Container')])).filter(([v]) => it.equipped || v !== (bagOf(it) ? it.bag : ''));
