  const L = artLv(), kMax = infKnownMax(L), kn = infKnownCount(), known = new Set(S.picks.infusion || []), reps = infReplicas();
  const tag = (lv, att) => `<span class="itag">${ordn(lv)}+</span>${att ? '<span class="itag att">attunement</span>' : ''}`;
