function spCatMove(id, d) { const a = S.spellCats || [], k = a.findIndex(c => c.id === id), t = k + d; if (k < 0 || t < 0 || t >= a.length) return; const x = a[k]; a[k] = a[t]; a[t] = x; pendingLabel = 'Move category: ' + x.name; save(); render(); }
