  ghost.className = 'sdrag-ghost'; ghost.textContent = (S.spells[N(h.dataset.sdrag)] || {}).name || ''; Object.assign(ghost.style, { left: r.left + 'px', top: r.top + 'px' }); document.body.appendChild(ghost);
